<script setup>
import {ref,computed} from 'vue'
import Icon from './Icon.vue'
const active=ref('学生拍照提交'),selected=ref(0)
const flows={
 '学生拍照提交':[{role:'教师',title:'发布作文任务',note:'选择班级、题目与评分方案，发布时锁定评分快照。',icon:'FileAddOutlined'},{role:'学生 App',title:'拍照并提交',note:'进入任务，拍摄多页作文，确认清晰度及页序。',icon:'CameraOutlined'},{role:'系统',title:'检查与收稿',note:'校验归属、图片完整性和重复提交，返回收稿回执。',icon:'InboxOutlined'},{role:'AI',title:'识别与分项初评',note:'识别文字，按题意与方案评价各维度，给出原文依据。',icon:'ReadOutlined'},{role:'规则引擎',title:'执行计分规则',note:'计算字数、错字分档及维度上限，标记边界问题。',icon:'CalculatorOutlined'},{role:'教师',title:'复核并发布',note:'核对原稿与评分，处理异常后发布正式成绩。',icon:'CheckCircleOutlined'},{role:'学生 App',title:'查看成绩反馈',note:'查看分项成绩、原文批注与改进建议，本次任务完成。',icon:'SolutionOutlined'}],
 '老师批量上传':[{role:'教师',title:'选择任务与班级',note:'进入任务收稿名单，批量上传照片或扫描文件。',icon:'TeamOutlined'},{role:'系统',title:'分组与身份匹配',note:'根据班号、姓名及页码提出分组，标记冲突和缺页。',icon:'ApartmentOutlined'},{role:'教师',title:'确认稿件归属',note:'确认学生与页序，处理未匹配和重复稿件。',icon:'UserSwitchOutlined'},{role:'AI',title:'识别与分项初评',note:'仅处理归属已确认的稿件，保留原图定位和评分证据。',icon:'ReadOutlined'},{role:'规则引擎',title:'执行计分规则',note:'执行维度上限和总分计算，异常进入复核队列。',icon:'CalculatorOutlined'},{role:'教师',title:'复核并发布',note:'逐篇确认后发布，批量发布仅包含已完成复核的结果。',icon:'CheckCircleOutlined'},{role:'学生 App',title:'查看成绩反馈',note:'老师上传后显示已收稿，无需学生重复提交。',icon:'SolutionOutlined'}],
